local config = {
  str_homestory_N17guide_90000101_1_dialog_content = "...",
  str_homestory_N17guide_90000101_2_dialog_content = "Hmm...",
  str_homestory_N17guide_90000101_3_dialog_content = "Vice?",
  str_homestory_N17guide_90000101_4_dialog_content = "O que você tá olhando?",
  str_homestory_N17guide_90000101_5_dialog_content = "Uma extensão de terra tão grande... Eu não pensei que Eraveil tivesse um lugar assim!",
  str_homestory_N17guide_90000101_6_dialog_content = "Como não percebemos isso em todas as nossas aventuras?!",
  str_homestory_N17guide_90000101_7_dialog_content = "Você não tem nenhuma lembrança de um lugar assim? Afinal, Eraveil é sua cidade natal...",
  str_homestory_N17guide_90000101_8_option_content = "Lembro.",
  str_homestory_N17guide_90000101_9_dialog_content = "Suponho que se possa dizer que tenho uma leve impressão disso. As estruturas e a flora aqui parecem bastante familiares.",
  str_homestory_N17guide_90000101_10_dialog_content = "Mas não consigo apontar onde já os vi antes... Talvez eu esteja enganado.",
  str_homestory_N17guide_90000101_11_dialog_content = "Afinal, este não é o mesmo Eraveil que vimos antes, então minhas memórias podem não ser tão confiáveis.",
  str_homestory_N17guide_90000101_12_dialog_content = "Isso faz sentido. Você era muito jovem na época, e este lugar estava muito bem escondido...",
  str_homestory_N17guide_90000101_13_option_content = "Eu não lembro.",
  str_homestory_N17guide_90000101_14_dialog_content = "Acho que nunca vi esse lugar.",
  str_homestory_N17guide_90000101_15_dialog_content = "As vagas lembranças que tenho de Eraveil são de suas outras áreas. Acho que nunca vim aqui quando era jovem.",
  str_homestory_N17guide_90000101_16_dialog_content = "Isso faz sentido, este lugar sempre foi muito bem escondido.",
  str_homestory_N17guide_90000101_17_dialog_content = "Eraveil é verdadeiramente misterioso. Há sempre surpresas à nossa espera.",
  str_homestory_N17guide_90000101_18_dialog_content = "Mal posso esperar para explorar este lugar!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_19_dialog_content = "Seu espírito de equipe interior da Exploração da Illumina despertou novamente?",
  str_homestory_N17guide_90000101_20_dialog_content = "Crrr, crrr...",
  str_homestory_N17guide_90000101_21_dialog_content = "Hã? O que é isso?",
  str_homestory_N17guide_90000101_22_dialog_content = "Parece algum tipo de máquina automatizada? Ou criatura?",
  str_homestory_N17guide_90000101_23_dialog_content = "Chubb, Chubb!",
  str_homestory_N17guide_90000101_24_dialog_content = "Está falando!",
  str_homestory_N17guide_90000101_25_dialog_content = "Bem-vindo bem vindo! Chubb! Chubb!",
  str_homestory_N17guide_90000101_26_dialog_content = "Parece muito feliz. Achei que era um dispositivo defensivo que nos marcaria como hostis...",
  str_homestory_N17guide_90000101_27_dialog_content = "Se não me engano, é feito de tecnologia Caelestite. Olha só o material de que é feito...",
  str_homestory_N17guide_90000101_28_dialog_content = "As marcas também... acho que vi algo parecido no Colossus...",
  str_homestory_N17guide_90000101_29_dialog_content = "Mas sua aparência boba é realmente algo, hein?",
  str_homestory_N17guide_90000101_30_dialog_content = "Chubb!! Quem você está chamando de bobo, Chubb!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N17guide_90000101_31_dialog_content = "Está com raiva. Tem um temperamento enorme para uma coisa tão pequena.",
  str_homestory_N17guide_90000101_32_dialog_content = "Vamos dar uma olhada ao redor. Podemos? ... É...",
  str_homestory_N17guide_90000101_33_dialog_content = "Hum, como devo te chamar?",
  str_homestory_N17guide_90000101_34_dialog_content = "Chubb.",
  str_homestory_N17guide_90000101_35_dialog_content = "... Chubb? Você inventou isso na hora?",
  str_homestory_N17guide_90000101_36_dialog_content = "Ele continua dizendo \"Chubb\".",
  str_homestory_N17guide_90000101_37_dialog_content = "Chubb! Belo nome, Chubb!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_38_dialog_content = "Ele realmente gosta deste nome?",
  str_homestory_N17guide_90000101_39_dialog_content = "Acho que nos aceitou!",
  str_homestory_N17guide_90000101_40_dialog_content = "Vamos lá, PlayerName! Vamos dar uma olhada ao redor!",
  str_homestory_N17guide_90000102_0_dialog_content = "Vice...",
  str_homestory_N17guide_90000102_1_dialog_content = "Já falei com Chubb aqui.",
  str_homestory_N17guide_90000102_2_dialog_content = "Eu praticamente entendi o que queria dizer... Na verdade, é muito simples!",
  str_homestory_N17guide_90000102_3_dialog_content = "O que? Vocês estão conversando agora?",
  str_homestory_N17guide_90000102_4_dialog_content = "Aprendeu o universo muito rapidamente. Até me deu um <color=#FFB400>Machado</color> e um <color=#FFB400>picareta</color>.",
  str_homestory_N17guide_90000102_5_dialog_content = "Um machado e uma picareta?",
  str_homestory_N17guide_90000102_6_dialog_content = "Sim. Acho que é para logar? Ou cavando?<sprite=emo_sikao size=60 />",
  str_homestory_N17guide_90000102_7_dialog_content = "De qualquer forma, acho que ele quer nossa ajuda para coletar alguns <color=#FFB400>materiais</color>.",
  str_homestory_N17guide_90000102_8_dialog_content = "Talvez seja para reparar os edifícios aqui?",
  str_homestory_N17guide_90000102_9_dialog_content = "De qualquer forma, vou deixar para você, PlayerName. Use-o como uma oportunidade para se exercitar.<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000102_10_dialog_content = "Eu nem tive a chance de recusar.<sprite=emo_xiaoku size=60 />",
  str_homestory_N17guide_90000102_11_dialog_content = "Fiz um resumo de algumas coisas que Chubb me contou, e as registrei neste <color=#FFB400>manual</color>.",
  str_homestory_N17guide_90000102_12_dialog_content = "Que rápido!",
  str_homestory_N17guide_90000103_1_dialog_content = "Chubb! Está reparado! Viva! Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_2_dialog_content = "Isso foi rápido! O que acabou de acontecer?",
  str_homestory_N17guide_90000103_3_dialog_content = "Acho que consertou a bancada em <color=#FFB400>Torre Jacinto</color>! Incrível!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000103_4_dialog_content = "Não é grande coisa, Chubb...<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000103_5_dialog_content = "Torre Jacinto? Você veio com esse nome no local também?",
  str_homestory_N17guide_90000103_6_dialog_content = "Não! Lembre-se da outra torre maior em Eraveil?",
  str_homestory_N17guide_90000103_7_dialog_content = "Elas são parecidas, e ambas são torres. Então, acabei de chamá-lo de Hyacinth Tower!",
  str_homestory_N17guide_90000103_8_dialog_content = "Mas este diante de nós é obviamente muito mais requintado. Eu me pergunto para que serve...",
  str_homestory_N17guide_90000103_9_dialog_content = "Por que você não tenta por si mesmo? Chubb!",
  str_homestory_N17guide_90000103_10_dialog_content = "Se for operado por este celestita aqui, com certeza funcionará, Chubb!",
  str_homestory_N17guide_90000103_11_dialog_content = "É assim mesmo? Então eu vou em frente!",
  str_homestory_N17guide_90000103_12_dialog_content = "PlayerName, Chubb quer que você experimente a bancada!",
  str_homestory_N17guide_90000103_13_dialog_content = "Parece que você é o mestre deste lugar.",
  str_homestory_N17guide_90000103_14_dialog_content = "Mestre...",
  str_homestory_N17guide_90000103_15_dialog_content = "Chubb, Chubb.",
  str_homestory_N17guide_90000103_16_dialog_content = "...",
  str_homestory_N17guide_90000103_17_dialog_content = "Isso mesmo, eu sou o mestre deste lugar agora.",
  str_homestory_N17guide_90000103_18_dialog_content = "Desculpe deixá-lo esperando por tanto tempo, Chubb.",
  str_homestory_N17guide_90000103_19_dialog_content = "Voltei!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000103_20_dialog_content = "Você voltou! Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_21_dialog_content = "Então, como o mestre deste lugar, você está planejando convidar seus amigos para visitar?",
  str_homestory_N17guide_90000103_22_dialog_content = "É claro! Mas onde todos vão ficar quando vierem?",
  str_homestory_N17guide_90000103_23_dialog_content = "Você pode usar o workbench para construir <color=#FFB400>Dormitório Jardins</color>! Chubb!",
  str_homestory_N17guide_90000103_24_dialog_content = "Há <color=#FFB400>dormitórios</color> aqui! Este lugar realmente tem um conjunto completo de instalações!",
  str_homestory_N17guide_90000103_25_dialog_content = "Vamos tentar!",
  str_homestory_N17guide_90000104_1_dialog_content = "<sprite=emo_hanshui size=60 />Ufa... Finalmente está feito!",
  str_homestory_N17guide_90000104_2_dialog_content = "Nunca pensei que construir fosse tão fácil. Eu esperava que demorasse muito.",
  str_homestory_N17guide_90000104_3_dialog_content = "Falando nisso, foi o mesmo no Colossus quando eu estava reformando os quartos. Eu era capaz de fazê-lo em um instante.",
  str_homestory_N17guide_90000104_4_dialog_content = "Esse é o poder da tecnologia? Nós, Caelestites, somos realmente incríveis.",
  str_homestory_N17guide_90000104_5_dialog_content = "Não é mesmo, Vi—",
  str_homestory_N17guide_90000104_6_dialog_content = "Vice?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000104_7_dialog_content = "Deste jeito, PlayerName!",
  str_homestory_N17guide_90000104_8_dialog_content = "Mal posso esperar para que os outros venham conferir este lugar!",
  str_homestory_N17guide_90000104_9_dialog_content = "Apresse-se e <color=#FFB400>convidar</color> eles acabaram!",
  str_homestory_N17guide_90000104_10_dialog_content = "Sim, está bem!",
  str_homestory_N17guide_90000105_1_dialog_content = "Olá, Sra. Blanc. Bem-vindo ao...",
  str_homestory_N17guide_90000105_2_dialog_content = "Hum...",
  str_homestory_N17guide_90000105_3_dialog_content = "... Meu <color=#FFB400>Jardins das Nuvens</color>.",
  str_homestory_N17guide_90000105_4_dialog_content = "Ha, você é muito bom em inventar nomes na hora também, PlayerName.",
  str_homestory_N17guide_90000105_5_dialog_content = "Eu tenho um bom professor.<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000105_6_dialog_content = "Cloud Gardens... Impressionante, é um nome elegante.",
  str_homestory_N17guide_90000105_7_dialog_content = "A paisagem aqui também é fantástica. Realmente faz você esquecer temporariamente todos os seus problemas...",
  str_homestory_N17guide_90000105_8_dialog_content = "Obrigado sinceramente por me convidar aqui, PlayerName.",
  str_homestory_N17guide_90000105_9_dialog_content = "Não mencione isso, Sra. Blanc. Sempre fomos camaradas em nossas aventuras, então agora devemos cultivar juntos também...",
  str_homestory_N17guide_90000105_10_dialog_content = "Aham!<sprite=emo_shengqi size=60 />",
  str_homestory_N17guide_90000105_11_dialog_content = "... Ah, eu quis dizer que podemos relaxar e apreciar a paisagem juntos!",
  str_homestory_N17guide_90000105_12_dialog_content = "Haha! Sem problemas! Farei minha parte para ajudar Cloud Gardens a florescer.",
  str_homestory_N17guide_90000105_13_dialog_content = "Vou aproveitar esta oportunidade para me familiarizar com os arredores para que eu possa me tornar um bom guia para futuros visitantes.",
  str_homestory_N17guide_90000105_14_dialog_content = "Você poderia me apresentar as outras instalações, PlayerName?",
  str_homestory_N17guide_90000105_15_dialog_content = "Permita-me, Sra. Blanc. Chubb acabou de me dizer muito mais!",
  str_homestory_N17guide_90000105_16_dialog_content = "Como <color=#FFB400>Torre Jacinto</color> for gradualmente aperfeiçoado, podemos usar sua bancada para <color=#FFB400>desbloquear ainda mais edifícios</color>.",
  str_homestory_N17guide_90000105_17_dialog_content = "o <color=#FFB400>Dormitórios Jardins</color> que acabamos de concluir pode acomodar todos que visitam!",
  str_homestory_N17guide_90000105_18_dialog_content = "Além disso, temos <color=#FFB400>Fonte de bênçãos</color>, localizado em frente à Hyacinth Tower.",
  str_homestory_N17guide_90000105_19_dialog_content = "Tem muitas surpresas reservadas para todos e certamente se tornará um ponto turístico popular!",
  str_homestory_N17guide_90000105_20_dialog_content = "Há um <color=#FFB400>museu</color> também. Os tesouros raros que obtivermos serão expostos lá...",
  str_homestory_N17guide_90000105_21_dialog_content = "Ah, tem mais!",
  str_homestory_N17guide_90000105_22_dialog_content = "Vice, desacelerar. A Sra. Blanc não consegue assimilar tudo tão rapidamente...",
  str_homestory_N17guide_90000105_23_dialog_content = "É verdade... Familiarizar-me aos poucos, conhecendo o local pessoalmente, também é uma boa ideia.",
  str_homestory_N17guide_90000105_24_dialog_content = "PlayerName, você tem certeza que não é porque você é o único que não consegue se lembrar de tudo?",
  str_homestory_N17guide_90000105_25_dialog_content = "<sprite=emo_xuanyun size=60 />E-É um pouco esmagador...",
  str_homestory_N17guide_90000105_26_dialog_content = "Eu tenho que lembrar para que serve cada prédio, e também me preparar para receber todos os outros...",
  str_homestory_N17guide_90000105_27_dialog_content = "Eu realmente não sei o que fazer com você. Aqui, deixe-me dar-lhe isto. Mantenha-o seguro...",
  str_homestory_N17guide_90000105_28_dialog_content = "Você pode usar isso <color=#FFB400>diário</color> para gravar sua vida diária em Cloud Gardens!",
  str_homestory_N17guide_90000105_29_dialog_content = "Faça registros de tudo o que acontece aqui para não ficar sobrecarregado!",
  str_homestory_N17guide_90000105_30_dialog_content = "Como você é atencioso, Vice.",
  str_homestory_N17guide_90000105_31_dialog_content = "PlayerName, se você está se sentindo cansado, eu sei a maneira perfeita de ajudá-lo a relaxar!",
  str_homestory_N17guide_90000105_32_dialog_content = "Ahn? O que é?",
  str_homestory_N17guide_90000105_33_dialog_content = "Hehe, me siga se quiser descobrir!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000106_0_dialog_content = "Hã?",
  str_homestory_N17guide_90000106_1_dialog_content = "Vice! Sua ideia de relaxamento é...",
  str_homestory_N17guide_90000106_2_dialog_content = "Isso mesmo! Isso é <color=#FFB400>pescaria</color>!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000106_3_dialog_content = "Não há nada mais relaxante do que desfrutar dos prazeres da pesca em um lugar tão bonito.",
  str_homestory_N17guide_90000106_4_dialog_content = "(Além disso... o peixe que pescamos pode ser <color=#FFB400>vendido</color>.)<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000106_5_dialog_content = "(Vice, eu posso praticamente sentir o cheiro da ganância saindo de você.)",
  str_homestory_N17guide_90000106_6_dialog_content = "<sprite=emo_hanshui size=60 />E-Esse não é o ponto... De qualquer forma, vamos tentar pescar!!",
  str_homestory_N17guide_90000106_7_dialog_content = "Aqui estão as varas de pesca! Vamos malhar!",
  str_homestory_N17guide_90000106_8_dialog_content = "Eu vi uma pá. Para que serve isto?",
  str_homestory_N17guide_90000106_9_dialog_content = "Ah, além de pescar, pretendo cavar por aí. Talvez eu encontre um tesouro.",
  str_homestory_N17guide_90000106_10_dialog_content = "Você está deixando suas intenções tão óbvias...",
  str_homestory_N17guide_90000106_11_dialog_content = "<sprite=emo_shengqi size=60 />Não exploramos antes também? Chama-se caça ao tesouro! Caça ao tesouro!",
  str_homestory_N17guide_90000106_12_dialog_content = "Você não precisa se preocupar se você se perder. Basta dar uma olhada no seu <color=#FFB400>mapa</color>.",
  str_homestory_N17guide_90000106_13_dialog_content = "Ok, então vamos pegar alguns peixes primeiro!",
  str_homestory_N17guide_90000107_1_dialog_content = "Yay! A loja é toda construída! Este lugar está lentamente ganhando vida!",
  str_homestory_N17guide_90000107_2_dialog_content = "Sim, de fato, Chubb! Estamos prontos para os negócios agora, Chubb!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000107_3_dialog_content = "Surpreendentemente, Chubbs com diferentes aparências são responsáveis por diferentes instalações...",
  str_homestory_N17guide_90000107_4_dialog_content = "Eles são tão fofos. Estou até pensando em levar um de volta para Lumopolis comigo!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000107_5_dialog_content = "Chu Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000107_6_dialog_content = "Então posso começar a ganhar dinheiro agora?",
  str_homestory_N17guide_90000107_7_dialog_content = "Sim, eu tenho todas as informações que você precisa.",
  str_homestory_N17guide_90000107_8_dialog_content = "A loja exibirá regularmente todos os tipos de <color=#FFB400>ordens</color>. Você será recompensado por completá-los.",
  str_homestory_N17guide_90000107_9_dialog_content = "Ganhar dinheiro sem ter que dar um passo para fora! Cloud Gardens é incrível!!<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000107_10_dialog_content = "Eu não esperava uma loja tão pequena, mas totalmente abastecida aqui. . .",
  str_homestory_N17guide_90000107_11_dialog_content = "Estou ainda mais impressionado com Cloud Gardens agora...",
  str_homestory_N17guide_90000107_12_dialog_content = "De uma chance, PlayerName! Vamos completar um pedido para começar!",
  str_homestory_N17guide_90000107_13_dialog_content = "Vamos!",
  str_homestory_N17guide_90000107_14_dialog_content = "Na verdade, por que estou sempre indo trabalhar com tanto entusiasmo?<sprite=emo_tanqi size=60 />",
  str_homestory_N17guide_90000107_15_dialog_content = "Esta é a sua própria casa, PlayerName! Anime-se!",
  str_homestory_N17guide_90000108_0_dialog_content = "Pronto!",
  str_homestory_N17guide_90000108_1_dialog_content = "Uau! A recompensa é bem legal!<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000108_2_dialog_content = "É ótimo ganhar dinheiro com minhas próprias mãos!",
  str_homestory_N17guide_90000108_3_dialog_content = "Já não montamos barracas e atendemos pedidos antes? Eu até levo todo mundo para lutar em Umbraton todos os dias...",
  str_homestory_N17guide_90000108_4_dialog_content = "Não é o mesmo! Esta tem sido uma experiência totalmente nova!",
  str_homestory_N17guide_90000108_5_dialog_content = "Hmm, gostaria de saber se há mais coisas na loja ...",
  str_homestory_N17guide_90000108_6_dialog_content = "Claro que existem.",
  str_homestory_N17guide_90000108_7_dialog_content = "Seriamente? Como você já sabe tanto sobre esse lugar?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000108_8_dialog_content = "Podes tentar <color=#FFB400>plantando uma árvore</color>.",
  str_homestory_N17guide_90000108_9_dialog_content = "As árvores aqui têm que ser plantadas? Achei que cresceriam naturalmente...",
  str_homestory_N17guide_90000108_10_dialog_content = "Não estou falando de nenhuma árvore comum, mas sim...",
  str_homestory_N17guide_90000108_11_dialog_content = "Existem esses tipos especiais de árvores chamadas <color=#FFB400>Árvores únicas</color>. Você ainda tem que preparar um especial <color=#FFB400>terreno fértil</color> apenas para eles.",
  str_homestory_N17guide_90000108_12_dialog_content = "Sério? Então vamos dar uma chance.",
  str_homestory_N17guide_90000108_13_dialog_content = "Quer saber, estou meio cansado. Estou voltando para a Hyacinth Tower para dar uma olhada nas contas.",
  str_homestory_N17guide_90000108_14_dialog_content = "Vice! Plantar árvores é trabalho físico!",
  str_homestory_N17guide_90000108_15_dialog_content = "A tecnologia Caelestite é muito avançada. Não há necessidade de trabalho físico.<sprite=emo_qingsong size=60 />",
  str_homestory_N17guide_90000108_16_dialog_content = "Ei-",
  str_homestory_N17guide_90000109_1_dialog_content = "Bom trabalho, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000109_2_dialog_content = "Cloud Gardens ficou tão bonito em tão pouco tempo!",
  str_homestory_N17guide_90000109_3_dialog_content = "Chubb, Chubb, Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000109_4_dialog_content = "Você trabalhou duro também Vice, dando-me todos os detalhes sobre este lugar.",
  str_homestory_N17guide_90000109_5_dialog_content = "Deve ser muito difícil entender a linguagem dos Chubbs, certo?",
  str_homestory_N17guide_90000109_6_dialog_content = "Você até me pediu para ajudar PlayerName lidar com a chegada dos outros Aurorianos.",
  str_homestory_N17guide_90000109_8_dialog_content = "Então você não tem afrouxado, Vice.",
  str_homestory_N17guide_90000109_9_dialog_content = "Claro que não! Esta é a nossa nova casa! Eu tenho que cuidar bem dele!",
  str_homestory_N17guide_90000109_10_dialog_content = "Além disso, tenho que calcular nossas novas receitas e despesas, sem contar que ainda temos que considerar nossas despesas regulares com o Colosso...",
